from heapq import heappush, heappop

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in range(1, len(graph) + 1)}
    distances[start] = 0

    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, edge_weight in graph[current_node].items():
            distance = current_distance + edge_weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def find_closest_pair(graph, start, end):
    distances = dijkstra(graph, start)
    min_distance = float('infinity')
    min_pair = None

    for node in range(1, len(graph) + 1):
        if distances[node] == float('infinity'):
            continue

        if node != start and node != end and node != start and node != end and distances[node] < min_distance:
            min_distance = distances[node]
            min_pair = (node, end)

    return min_pair

