MOD = 10**9 + 7

def find_parent(node, parent):
    if node != parent[node]:
        parent[node] = find_parent(parent[node], parent)
    return parent[node]

def union_parent(parent, a, b):
    a = find_parent(a, parent)
    b = find_parent(b, parent)
    if a < b:
        parent[a] = b
    else:
        parent[b] = a

def count_triples(parent, values):
    triples = 0
    max_depth = 0
    for i, value in enumerate(values):
        depth = -1
        for k, value2 in enumerate(values):
            if find_parent(k, parent) != find_parent(i, parent):
                depth = max(depth, abs(value - value2))
        if depth > max_depth:
            triples = 1
        else:
            triples *= sum(values[k] * values[(i - 1) // (depth - k)] % MOD for k in range(value, i))
            triples %= MOD
        max_depth = max(max_depth, depth)
    return triples

def solve(N, edges, values):
    parent = [-1] * (N + 1)
    for u, v in edges:
        union_parent(parent, u, v)
    return count_triples(parent, values)

