def calculate_cubes(N, tile_corners):
    tile_count = [[0] * 4 for _ in range(N)]
    direction_lookup = {
        0: [(0, 0), (1, -1), (-1, 1), (-1, -1)],  # Vertical rotation
        1: [(1, 0), (-1, 0), (-1, -1), (1, -1)],  # Horizontal rotation
        2: [(0, 0), (1, 0), (1, -1), (1, 1)],
        3: [-1, -1, -1, -1]  # Rewrite to avoid repetition
    }

    dp = [0] * (1 << N)
    dp[1] = 1

    for tile_number in range(1, N + 1):
        for tiles_left in range(1 << tile_number):
            corner_mask = tiles_left & (tiles_left - 1)
            for direction_bit in range(N):
                if corner_mask & (1 << direction_bit) == 0:
                    next_tile = tile_corners[tile_number-1][direction_lookup[direction_bit][0]]
                    if next_tile:
                        masked_tile = (next_tile & tiles_left) >> direction_bit
                        if masked_tile:
                            px, py, pz = direction_lookup[direction_bit]
                            cpx, cpy, cpz = direction_lookup[px // 2][py // 2]
                            dp[tiles_left | (1 << tile_number)] += dp[tiles_left]

    return dp[(1 << N) - 1]

