import sys

def find_min_distance(mice, holes, distances):
    dp = [-1] * (mice + 1)

    def dfs(mouse, prev_distance, states, mem):
        if mouse <= 0: 
            return 0
        code = (mouse, prev_distance, tuple(states))
        if mem.get(code):
            return mem[code]
        mn = sys.maxsize
        for hole in range(mice):
            if states[hole] + 1 < holes[hole]:
                newstates = list(states)
                newstates[hole] += 1
                mn = min(mn, abs(mice[mouse] - distance(mice[mouse], hole)) + dfs(mouse - newstates[hole], distance(mice[mouse], hole), newstates, mem))
        mem[code] = min(mn, dfs(mouse - 1, 0, states, mem))
        return mem[code]

