        for i in range(N):
            row = []
            for j in range(N):
                value = colors[(i + dx) % N][(j + dy) % N][(j + dz) % N] % 3
                row.append(colors[(i + dx + value) % N][(j + dy + 1 + value) % N][(j + dz + 2 + value) % N])
            new_cube.append(row)
        return new_cube

