def dijkstra(graph, start):
    import heapq
    queue = [(0, start)]
    dist = {start: 0}
    while queue:
        (cost, u) = heapq.heappop(queue)
        if u not in dist:
            dist[u] = cost
            for v, w in graph[u]:
                if v in dist and dist[u] + 2 * w < dist[v]:
                    dist[v] = dist[u] + 2 * w
                    heapq.heappush(queue, (dist[v], v))
                elif v not in dist:
                    dist[v] = dist[u] + 2 * w
                    heapq.heappush(queue, (dist[v], v))
    return dist

