    if color_query_type == 'C':
        leaf_index = int(indices[color_query_type])
        r_children = []
        b_children = []
        for i in tree[leaf_index]:
            b_children.append(roots[i])
        for i in tree[leaf_index]:
            r_children.append(i)
        b_count = sum(1 for i in tree if i in r_children)
        r_count = sum(1 for i in tree if i in b_children)
        if b_count - r_count >= int(k_value == color_query_type):
            color = 0
        else:
            color = 1
        return color
    elif color_query_type in 'CF':
        k = int(k_value)
        do_size_change = int(color_query_type == 'C')
        if len(tree) <= k + 1:
            leaves = [i for i in tree if len(tree[i]) == 1 and tree[i][0] != index]
            color = 2 - sum(1 for i in leaves if tree[i][0] == index)
        else:
            new_children_to_check = tree[index]
            count = 0
            for i in leaves:
                if tree[i] in tree:
                    new_children_to_check.extend(tree[i])
                else:
                    count += 1
                if count == k + 1:
                    break
            color = sum(2 - [1 for child in new_children_to_check if child in tree] for child in tree[index])
        return color
