        _, ci, sj = heappop(min_heap)
        if ci >= n:
            result = min(result, -sj * Cs[sj])
        else:
            distances.insert(len(distances), (ps[ci], -Cs[ci]))

        for j in range(len(distances)):
            heappush(min_heap, (distances[j][0] - xs[ci], ci, j))

    return result if result < float('inf') else -1
