from collections import defaultdict

def min_cost_to_disconnect(s, t, paths):
    graph = defaultdict(list)
    path_cost = defaultdict(int)

    # Build the graph
    for path in paths:
        start, end, cost = path
        graph[start].append(end)
        graph[end].append(start)
        path_cost[path] = cost

    # Try to disconnect using two roads
    best_cost, best_roads = float('inf'), 0
    visited = [False] * (n + 1)
    visited[s] = True
    for road in find_paths_util(s, t, visited):
        if len(visited) - sum(1 for v in visited if v) > 2:
            continue
        if graph[road[0]].index(t) + 1 and graph[road[1]].index(road[0]) + 1:
            cost = sum(path_cost[(road[i], road[i + 1])] for i in range(2, len(road) - 1))
            if cost < best_cost:
                best_cost = cost
                best_roads = [graph.index(road) for road in find_paths_util(road[0], road[1], visited)]

    return best_cost, len(best_roads)

def find_paths_util(start, end, visited):
    if start == end:
        yield [start]
    else:
        for node in graph[start]:
            if not visited[node]:
                visited[node] = True
                for path in find_paths_util(node, end, visited):
                    yield [start] + path
                visited[node] = False

