def min_cost_break_relationship(s, t, roads):
    # The problem can be modeled as a minimum cost flow problem
    import sys
    from heapq import heappush, heappop

    n, m = len(roads) + 2, len(roads)
    # Adding an extra vertex for s and t
    G = [[] for _ in range(m + 2)]
    for u, v, w in roads:
        G[u].append((v, w))
        G[v].append((u, w))

    # Initialize capacities
    for i in range(1, m + 2):
        G[i].append((t, sys.maxsize))
        G[t].append((i, sys.maxsize))

    # Compute max flow
    # We don't need C_max to compute max flow, but it is safer to assume that max flow exists
    def callback(xmin, xmax):
        cost = 0
        for i in range(m + 2):
            for u, w in G[i]:
                cost += min(w, cap[i][u]) * (cap[i][u]/w - xmin)
        return cost
    # Assume that max flow exists
    cap = [[1] * (m + 2) for _ in range(m + 2)]
    Tmin, Tmax = 1, m+1
    Q = [(Tmin, 0)]
    while len(Q) != 0:
        tmin, flow = heappop(Q)
        if flow < tmin:
            for i in range(m + 2):
                for u, w in G[i]:
                    if w >= Q[-1][1]:
                        cap[i][u] = 0
                        heappush(Q, (tmin, min(w, cap[i][u])))
                    elif w < Tmin:
                        if w == 0:
                            continue
                        if Q[-1][1] >= w:
                            Q.append((tmin, min(w, cap[i][u])))
                        else:
                            c = flow - Q[-1][1]
                            cap[i][u] = min(w - c, min(w, c * cap[i][u] - w * (cap[i][u]/w - c) + cap[i][u]/w * w))
                            heappush(Q, (tmin, min(w - c, cap[i][u])))
            for i in range(m + 1, mx):
                for u, w in G[i]:
                    if w >= Q[-1][1]:
                        stostmnop = (w, i) if w < Tmin else (w - Q[-1][1], Q[-1][0])
                        cap[i][u] = 0
                        heappush(Q, (tmin, stostnop))
    return callback(Tmin, Tmax) - sum(g for _, g in filter(lambda r: r[0] == s or r[1] == t, G)) 

