def read_input():
    T = int(input().strip())
    for _ in range(T):
        N, Q = map(int, input().strip().split())
        A = list(map(int, input().strip().split()))
        edges = [list(map(int, input().strip().split())) for _ in range(N-1)]
        queries = [list(map(int, input().strip().split())) for _ in range(Q)]
        yield T, N, Q, A, edges, queries

def compute_distance(parent, x, y):
    """
    Computes the sum of weights of the edges in the path from vertex "x" to vertex "y".
    """
    path = [y]
    while x != y:
        for edge in edges:
            if edge[0] == parent[x]:
                path.append(edge[1])
                x = edge[1]
                break
    return sum(A[v] for v in path)

def solve(parent, x, y, query):
    """
    Computes the sum for the given query.
    """
    answer = 0
    for u, v, w in edges:
        if u == query[0] and v == query[1] or u == query[1] and v == query[0]:
            continue
        path = [parent[v], v]
        dist = 0
        while path[0] != path[1]:
            for edge in edges:
                if edge[0] == path[1]:
                    dist += A[edge[1]]
                    path.append(edge[1])
                    path.append(edge[0])
                    break
            for edge in edges:
                if edge[0] == parent[path[1]]:
                    path[1] = edge[0]
                    break
            if path[1] == u:
                break
        dist += A[u]
        ans = x * dist - dist * y
        answer += ans
        # print(f"u: {u} v: {v} w: {w} path: {path} answer: {ans} dist: {dist}")
    return answer

def main():
    for T, N, Q, A, edges, queries in read_input():
        parent = [i] * N
        for parent_size in range(1, N):
            for i in range(parent_size, N):
                if i % parent_size == 0:
                    parent[i] = i - parent_size
        # print(parent)
        queries.sort()
        results = []
        for x, y in queries:
            results.append(solve(parent, x-1, y-1, (x, y)))
        print(*results, sep='\n')

if __name__ == "__main__":
    main()
