    return [i for i, j in enumerate(sieve) if j and i != 0]

def factorize(n):
    """Return the prime factors of n."""
    i = 2
    factors = []
    while i * i <= n:
        while (n % i) == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

